function CostCard({ cost }) {

    return (

        <div style={{
            marginTop: '30px',
            background: 'white',
            padding: '20px',
            borderRadius: '16px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.08)',
            maxWidth: '350px'
        }}>

            <h2>Cost Analysis</h2>

            <p>
                <strong>Total Units:</strong> {cost.totalUnits} kWh
            </p>

            <p>
                <strong>Rate Per Unit:</strong> ₹{cost.ratePerUnit}
            </p>

            <p>
                <strong>Estimated Cost:</strong> ₹{cost.estimatedCost}
            </p>

        </div>

    );

}

export default CostCard;
